({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const [tareas, setTareas] = useState([]);
  const [prioridades, setPrioridades] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const [resTareas, resPrio] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`),
      MEITI.fetchDatos(`/api/boveda/${MEITI.obtenerTabla('mt_prioridades')}?ecosistema=${eco}`)
    ]);
    if (resTareas.ok) setTareas(resTareas.registros || []);
    if (resPrio.ok) setPrioridades(resPrio.registros || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const completarTarea = async (tarea) => {
    const mutaciones = [];
    const hoy = new Date().toISOString().split('T')[0];

    mutaciones.push({
      url: `/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${tarea.id}`,
      opciones: {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...tarea, completada: 1, fecha_completada: hoy })
      }
    });

    if (tarea.regla_repeticion && tarea.regla_repeticion !== 'none') {
      let nuevaFecha = new Date(tarea.fecha || hoy);
      if (tarea.regla_repeticion === 'diaria') nuevaFecha.setDate(nuevaFecha.getDate() + 1);
      else if (tarea.regla_repeticion === 'semanal') nuevaFecha.setDate(nuevaFecha.getDate() + 7);
      else if (tarea.regla_repeticion === 'mensual') nuevaFecha.setMonth(nuevaFecha.getMonth() + 1);

      mutaciones.push({
        url: `/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`,
        opciones: {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            ...tarea,
            id: 'tar_' + Date.now(),
            completada: 0,
            fecha_completada: null,
            fecha: nuevaFecha.toISOString().split('T')[0],
            fecha_registro: new Date().toISOString()
          })
        }
      });
    }

    await MEITI.mutarVarias(mutaciones, {
      alLograr: cargar,
      alFallar: setError
    });
  };

  const abrirTarea = async (id) => {
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_estado_ui')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'estado_' + uid, usuario_id: uid, tarea_activa_id: id })
    }, {
      alLograr: () => MEITI.irAPagina('detalle_tarea'),
      alFallar: setError
    });
  };

  const hoyStr = new Date().toISOString().split('T')[0];
  const tareasHoy = tareas.filter(t => t.fecha === hoyStr && t.completada === 0 && !t.tarea_padre_id);
  const tareasAtrasadas = tareas.filter(t => t.fecha && t.fecha < hoyStr && t.completada === 0 && !t.tarea_padre_id);
  const completadasHoy = tareas.filter(t => t.fecha_completada === hoyStr && t.completada === 1).length;

  const getPrioLevel = (id) => {
    const p = prioridades.find(x => x.id === id);
    return p ? Number(p.nivel) : 99;
  };

  tareasHoy.sort((a, b) => getPrioLevel(a.prioridad_id) - getPrioLevel(b.prioridad_id));
  tareasAtrasadas.sort((a, b) => getPrioLevel(a.prioridad_id) - getPrioLevel(b.prioridad_id));

  const renderTarea = (t) => {
    const prio = prioridades.find(x => x.id === t.prioridad_id);
    const color = prio ? prio.color : tema.texto;
    return (
      <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key={t.id} className="flex items-center gap-3 p-3 rounded-xl mb-2 cursor-pointer hover:opacity-80 transition-opacity" style={{ backgroundColor: tema.superficie }} onClick={() => abrirTarea(t.id)}>
        <button onClick={(e) => { e.stopPropagation(); completarTarea(t); }} className="w-6 h-6 rounded-full border-2 flex items-center justify-center shrink-0" style={{ borderColor: color }}>
          <div className="w-4 h-4 rounded-full opacity-0 hover:opacity-100 transition-opacity" style={{ backgroundColor: color }}></div>
        </button>
        <div className="flex-1 min-w-0">
          <p className="font-bold text-sm truncate" style={{ color: tema.texto }}>{t.titulo}</p>
          {t.descripcion && <p className="text-xs opacity-60 truncate" style={{ color: tema.texto }}>{t.descripcion}</p>}
        </div>
        {t.regla_repeticion && t.regla_repeticion !== 'none' && <Iconos.Repeat size={14} color={tema.colorSecundario} className="shrink-0" />}
      </Animacion.motion.div>
    );
  };

  return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <UI.Tarjeta className="p-5 rounded-3xl flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-black" style={{ color: tema.texto }}>{MEITI.t('today', null, 'Hoy')}</h2>
          <p className="opacity-70 text-sm capitalize" style={{ color: tema.texto }}>{new Date().toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
        </div>
        <div className="flex flex-col items-center justify-center w-16 h-16 rounded-full border-4" style={{ borderColor: tema.colorPrimario, color: tema.colorPrimario }}>
          <span className="text-xl font-black">{completadasHoy}</span>
        </div>
      </UI.Tarjeta>

      {cargando ? <div className="text-center p-4"><Iconos.Loader className="animate-spin mx-auto" color={tema.colorPrimario} /></div> : (
        <>
          {tareasAtrasadas.length > 0 && (
            <div>
              <h3 className="font-bold mb-3 flex items-center gap-2" style={{ color: '#ef4444' }}><Iconos.CalendarClock size={18} /> {MEITI.t('overdue', null, 'Atrasadas')}</h3>
              {tareasAtrasadas.map(renderTarea)}
            </div>
          )}

          <div>
            <h3 className="font-bold mb-3 flex items-center gap-2" style={{ color: tema.texto }}><Iconos.Sun size={18} color={tema.colorSecundario} /> {MEITI.t('for_today', null, 'Para hoy')}</h3>
            {tareasHoy.length === 0 ? (
              <UI.EstadoVacio icono="fa-mug-hot" mensaje={MEITI.t('no_tasks_today', null, 'No tienes tareas pendientes para hoy. ¡Disfruta tu día!')} />
            ) : (
              tareasHoy.map(renderTarea)
            )}
          </div>
        </>
      )}

      <div className="fixed bottom-24 right-4 z-30">
        <button onClick={() => abrirTarea('')} className="w-14 h-14 rounded-full shadow-lg flex items-center justify-center transition-transform active:scale-95" style={{ backgroundColor: tema.colorPrimario, color: '#fff' }}>
          <Iconos.Plus size={28} />
        </button>
      </div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const [tareas, setTareas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`);
    if (res.ok) setTareas(res.registros.filter(t => t.completada === 0 && !t.tarea_padre_id) || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const hoy = new Date();
  const dias = [];
  for (let i = 1; i <= 7; i++) {
    const d = new Date(hoy);
    d.setDate(d.getDate() + i);
    dias.push(d.toISOString().split('T')[0]);
  }

  const cambiarFecha = async (tarea, nuevaFecha) => {
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${tarea.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...tarea, fecha: nuevaFecha })
    }, {
      alLograr: cargar,
      alFallar: setError
    });
  };

  const abrirTarea = async (id) => {
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_estado_ui')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'estado_' + uid, usuario_id: uid, tarea_activa_id: id })
    }, {
      alLograr: () => MEITI.irAPagina('detalle_tarea'),
      alFallar: setError
    });
  };

  return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <h2 className="text-2xl font-black px-2" style={{ color: tema.texto }}>{MEITI.t('next_7_days', null, 'Próximos 7 Días')}</h2>

      {cargando ? <div className="text-center p-4"><Iconos.Loader className="animate-spin mx-auto" color={tema.colorPrimario} /></div> : (
        <div className="flex flex-col gap-6">
          {dias.map(dia => {
            const tareasDia = tareas.filter(t => t.fecha === dia);
            const dateObj = new Date(dia + 'T12:00:00');
            return (
              <div key={dia}>
                <h3 className="font-bold mb-3 border-b pb-1 capitalize" style={{ color: tema.colorSecundario, borderColor: tema.colorSecundario + '33' }}>
                  {dateObj.toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'short' })}
                </h3>
                {tareasDia.length === 0 ? (
                  <p className="text-sm opacity-50 italic" style={{ color: tema.texto }}>{MEITI.t('no_tasks_scheduled', null, 'Sin tareas programadas')}</p>
                ) : (
                  tareasDia.map(t => (
                    <Animacion.motion.div initial={{ opacity: 0, x: -10 }} animate={{ opacity: 1, x: 0 }} key={t.id} className="flex items-center gap-3 p-3 rounded-xl mb-2" style={{ backgroundColor: tema.superficie }}>
                      <div className="flex-1 cursor-pointer min-w-0" onClick={() => abrirTarea(t.id)}>
                        <p className="font-bold text-sm truncate" style={{ color: tema.texto }}>{t.titulo}</p>
                      </div>
                      <input type="date" value={t.fecha || ''} onChange={(e) => cambiarFecha(t, e.target.value)} className="text-xs p-1 rounded bg-transparent border shrink-0" style={{ color: tema.texto, borderColor: tema.texto + '33' }} />
                    </Animacion.motion.div>
                  ))
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const [tareas, setTareas] = useState([]);
  const [nueva, setNueva] = useState('');
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`);
    if (res.ok) setTareas(res.registros.filter(t => t.completada === 0 && !t.fecha && !t.proyecto_id && !t.tarea_padre_id) || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const agregar = async (e) => {
    e.preventDefault();
    if (!nueva.trim()) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: 'tar_' + Date.now(),
        usuario_id: uid,
        titulo: nueva.trim(),
        completada: 0,
        fecha_registro: new Date().toISOString()
      })
    }, {
      alLograr: () => { setNueva(''); cargar(); },
      alFallar: setError
    });
  };

  const abrirTarea = async (id) => {
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_estado_ui')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ id: 'estado_' + uid, usuario_id: uid, tarea_activa_id: id })
    }, {
      alLograr: () => MEITI.irAPagina('detalle_tarea'),
      alFallar: setError
    });
  };

  return (
    <div className="flex flex-col gap-6 pb-28">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <h2 className="text-2xl font-black px-2" style={{ color: tema.texto }}>{MEITI.t('inbox', null, 'Bandeja de Entrada')}</h2>

      <UI.Tarjeta className="p-4 rounded-3xl">
        <form onSubmit={agregar} className="flex items-center gap-2">
          <div className="flex-1">
            <UI.Campo tipo="text" valor={nueva} onChange={e => setNueva(e.target.value)} placeholder={MEITI.t('add_quick_task', null, 'Añadir tarea rápida...')} />
          </div>
          <button type="submit" aria-label={MEITI.t('send', null, 'Enviar')} className="w-12 h-12 rounded-xl flex items-center justify-center shrink-0 transition-transform active:scale-95" style={{ backgroundColor: tema.colorPrimario, color: '#fff' }}>
            <Iconos.Send size={20} />
          </button>
        </form>
      </UI.Tarjeta>

      {cargando ? <div className="text-center p-4"><Iconos.Loader className="animate-spin mx-auto" color={tema.colorPrimario} /></div> : (
        <div className="flex flex-col gap-2">
          {tareas.length === 0 ? (
            <UI.EstadoVacio icono="fa-inbox" mensaje={MEITI.t('empty_inbox', null, 'Tu bandeja está vacía. Todo está organizado.')} />
          ) : (
            tareas.map(t => (
              <Animacion.motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} key={t.id} className="flex items-center gap-3 p-4 rounded-2xl cursor-pointer hover:opacity-80 transition-opacity" style={{ backgroundColor: tema.superficie }} onClick={() => abrirTarea(t.id)}>
                <Iconos.Circle size={20} color={tema.texto} className="opacity-30 shrink-0" />
                <p className="font-bold text-sm flex-1 truncate" style={{ color: tema.texto }}>{t.titulo}</p>
                <Iconos.ChevronRight size={16} color={tema.texto} className="opacity-30 shrink-0" />
              </Animacion.motion.div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const [proyectos, setProyectos] = useState([]);
  const [tareas, setTareas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);
  const [nuevo, setNuevo] = useState('');
  const [editando, setEditando] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const [resProj, resTar] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_proyectos')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`)
    ]);
    if (resProj.ok) setProyectos(resProj.registros || []);
    if (resTar.ok) setTareas(resTar.registros || []);
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const agregar = async (e) => {
    e.preventDefault();
    if (!nuevo.trim()) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_proyectos')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: 'proj_' + Date.now(),
        usuario_id: uid,
        nombre: nuevo.trim(),
        color: tema.colorPrimario
      })
    }, {
      alLograr: () => { setNuevo(''); cargar(); },
      alFallar: setError
    });
  };

  const guardarEdicion = async (e) => {
    e.preventDefault();
    if (!editando || !editando.nombre.trim()) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_proyectos')}?ecosistema=${eco}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(editando)
    }, {
      alLograr: () => { setEditando(null); cargar(); },
      alFallar: setError
    });
  };

  const borrar = async (id) => {
    if (await MEITI.confirmar(MEITI.t('delete_project_q', null, '¿Borrar este proyecto?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('delete_yes', null, 'Sí, borrar'), tono: 'peligro' })) {
      await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_proyectos')}?ecosistema=${eco}`, {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id })
      }, {
        alLograr: cargar,
        alFallar: setError
      });
    }
  };

  const columnas = [
    {
      clave: 'nombre',
      etiqueta: MEITI.t('name', null, 'Nombre'),
      render: (p) => (
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full shrink-0" style={{ backgroundColor: p.color || tema.colorPrimario }}></div>
          <span className="font-bold">{p.nombre}</span>
        </div>
      )
    },
    {
      clave: 'progreso',
      etiqueta: MEITI.t('progress', null, 'Progreso'),
      render: (p) => {
        const tareasProj = tareas.filter(t => t.proyecto_id === p.id && !t.tarea_padre_id);
        const completadas = tareasProj.filter(t => t.completada === 1).length;
        const total = tareasProj.length;
        const pct = total > 0 ? Math.round((completadas / total) * 100) : 0;
        return (
          <div className="flex flex-col gap-1 min-w-32">
            <div className="flex justify-between text-xs opacity-70">
              <span>{pct}%</span>
              <span>{completadas}/{total}</span>
            </div>
            <div className="w-full h-2 rounded-full overflow-hidden" style={{ backgroundColor: tema.fondo }}>
              <div className="h-full rounded-full transition-all" style={{ width: `${pct}%`, backgroundColor: p.color || tema.colorPrimario }}></div>
            </div>
          </div>
        );
      }
    }
  ];

  return (
    <div className="flex flex-col gap-6">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="flex flex-col gap-2">
        <h2 className="text-2xl font-black px-2" style={{ color: tema.texto }}>{MEITI.t('projects', null, 'Proyectos')}</h2>
        <p className="px-2 opacity-70 text-sm" style={{ color: tema.texto }}>{MEITI.t('projects_desc', null, 'Gestiona tus proyectos y mide su avance.')}</p>
      </div>

      {editando ? (
        <UI.Tarjeta className="p-4">
          <h3 className="font-bold mb-4" style={{ color: tema.texto }}>{MEITI.t('edit_project', null, 'Editar Proyecto')}</h3>
          <form onSubmit={guardarEdicion} className="flex flex-col md:flex-row gap-4 items-end">
            <div className="flex-1 w-full">
              <UI.Campo 
                etiqueta={MEITI.t('name', null, 'Nombre')}
                tipo="text" 
                valor={editando.nombre} 
                onChange={e => setEditando({...editando, nombre: e.target.value})} 
              />
            </div>
            <div className="flex gap-2 w-full md:w-auto">
              <div className="flex-1">
                <UI.Boton variante="secundario" onClick={() => setEditando(null)}>{MEITI.t('cancel', null, 'Cancelar')}</UI.Boton>
              </div>
              <div className="flex-1">
                <UI.Boton tipo="submit" variante="primario">{MEITI.t('save', null, 'Guardar')}</UI.Boton>
              </div>
            </div>
          </form>
        </UI.Tarjeta>
      ) : (
        <UI.Tarjeta className="p-4">
          <form onSubmit={agregar} className="flex flex-col md:flex-row gap-4 items-end">
            <div className="flex-1 w-full">
              <UI.Campo 
                etiqueta={MEITI.t('new_project', null, 'Nuevo proyecto')}
                tipo="text" 
                valor={nuevo} 
                onChange={e => setNuevo(e.target.value)} 
                placeholder={MEITI.t('project_name_placeholder', null, 'Ej: Rediseño web...')}
              />
            </div>
            <div className="w-full md:w-auto">
              <UI.Boton tipo="submit" variante="primario">{MEITI.t('add', null, 'Agregar')}</UI.Boton>
            </div>
          </form>
        </UI.Tarjeta>
      )}

      <div className="flex-1 min-h-0 flex flex-col">
        {cargando ? (
          <div className="p-8 text-center opacity-50">{MEITI.t('loading', null, 'Cargando...')}</div>
        ) : proyectos.length === 0 ? (
          <UI.EstadoVacio icono="fa-folder-open" mensaje={MEITI.t('no_projects', null, 'No tienes proyectos creados.')} />
        ) : (
          <UI.Tarjeta className="flex-1 min-h-0 flex flex-col">
            <div className="flex-1 overflow-y-auto min-h-0">
              <UI.TablaDatos 
                columnas={columnas}
                datos={proyectos}
                claveId="id"
                onEditar={(fila) => setEditando(fila)}
                onBorrar={(fila) => borrar(fila.id)}
              />
            </div>
          </UI.Tarjeta>
        )}
      </div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();

  const [tareaId, setTareaId] = useState(null);
  const [form, setForm] = useState({ id: '', titulo: '', descripcion: '', fecha: '', prioridad_id: '', proyecto_id: '', regla_repeticion: 'none' });
  const [subtareas, setSubtareas] = useState([]);
  const [nuevaSub, setNuevaSub] = useState('');
  const [subtareaEditando, setSubtareaEditando] = useState(null);

  const [proyectos, setProyectos] = useState([]);
  const [prioridades, setPrioridades] = useState([]);

  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const cargar = async () => {
    setCargando(true);
    const [resEst, resProj, resPrio] = await Promise.all([
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_estado_ui')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_proyectos')}?ecosistema=${eco}`),
      MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_prioridades')}?ecosistema=${eco}`)
    ]);

    if (resProj.ok) setProyectos(resProj.registros || []);
    if (resPrio.ok) setPrioridades(resPrio.registros || []);

    let tId = null;
    if (resEst.ok && resEst.registros.length > 0) {
      tId = resEst.registros[0].tarea_activa_id;
      setTareaId(tId);
    }

    if (tId) {
      const resTar = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`);
      if (resTar.ok) {
        const t = resTar.registros.find(x => x.id === tId);
        if (t) {
          setForm({
            id: t.id,
            titulo: t.titulo || '',
            descripcion: t.descripcion || '',
            fecha: t.fecha || '',
            prioridad_id: t.prioridad_id || '',
            proyecto_id: t.proyecto_id || '',
            regla_repeticion: t.regla_repeticion || 'none'
          });
        }
        setSubtareas(resTar.registros.filter(x => x.tarea_padre_id === tId));
      }
    } else {
      setForm({ ...form, id: 'tar_' + Date.now() });
    }
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    if (e) e.preventDefault();
    if (!form.titulo.trim()) return setError(MEITI.t('title_required', null, 'El título es obligatorio'));
    setGuardando(true);
    setError(null);

    const payload = {
      ...form,
      usuario_id: uid,
      completada: 0,
      fecha_registro: form.fecha_registro || new Date().toISOString()
    };

    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`, {
      method: tareaId ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('task_saved', null, 'Tarea guardada'));
        setTimeout(() => setExito(null), 3000);
        if (!tareaId) MEITI.irAPagina('inicio');
        setGuardando(false);
      },
      alFallar: (err) => { setError(err); setGuardando(false); }
    });
  };

  const agregarSubtarea = async () => {
    if (!nuevaSub.trim() || !tareaId) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        id: 'tar_' + Date.now(),
        usuario_id: uid,
        titulo: nuevaSub.trim(),
        tarea_padre_id: tareaId,
        completada: 0,
        fecha_registro: new Date().toISOString()
      })
    }, {
      alLograr: () => { setNuevaSub(''); cargar(); },
      alFallar: setError
    });
  };

  const guardarEdicionSubtarea = async () => {
    if (!subtareaEditando || !subtareaEditando.titulo.trim()) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${subtareaEditando.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(subtareaEditando)
    }, {
      alLograr: () => { setSubtareaEditando(null); cargar(); },
      alFallar: setError
    });
  };

  const borrarSubtarea = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('delete_subtask_q', null, '¿Borrar esta subtarea?'))) return;
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${id}`, {
      method: 'DELETE'
    }, {
      alLograr: cargar,
      alFallar: setError
    });
  };

  const borrarTarea = async () => {
    if (!tareaId) return;
    if (!await MEITI.confirmar(MEITI.t('delete_task_q', null, '¿Borrar esta tarea y sus subtareas?'))) return;

    const mutaciones = subtareas.map(s => ({
      url: `/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${s.id}`,
      opciones: { method: 'DELETE' }
    }));
    mutaciones.push({
      url: `/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${tareaId}`,
      opciones: { method: 'DELETE' }
    });

    await MEITI.mutarVarias(mutaciones, {
      alLograr: () => MEITI.irAPagina('inicio'),
      alFallar: setError
    });
  };

  const toggleSubtarea = async (sub) => {
    await MEITI.mutar(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}&id=${sub.id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...sub, completada: sub.completada ? 0 : 1 })
    }, {
      alLograr: cargar,
      alFallar: setError
    });
  };

  if (cargando) return <div className="p-8 flex justify-center"><i className="fa-solid fa-circle-notch fa-spin text-3xl" style={{ color: tema.colorPrimario }}></i></div>;

  return (
    <div className="flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <UI.Boton variante="secundario" onClick={() => MEITI.irAPagina('inicio')} ariaLabel={MEITI.t('back', null, 'Volver')}>
          <i className="fa-solid fa-arrow-left"></i>
        </UI.Boton>
        <h2 className="text-xl font-bold" style={{ color: tema.texto }}>
          {tareaId ? MEITI.t('edit_task', null, 'Editar Tarea') : MEITI.t('new_task', null, 'Nueva Tarea')}
        </h2>
        {tareaId ? (
          <UI.Boton variante="peligro" onClick={borrarTarea} ariaLabel={MEITI.t('delete', null, 'Borrar')}>
            <i className="fa-solid fa-trash"></i>
          </UI.Boton>
        ) : <div className="w-10"></div>}
      </div>

      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
      <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

      <UI.Tarjeta className="p-5">
        <div className="flex flex-col gap-4">
          <UI.Campo etiqueta={MEITI.t('title', null, 'Título')} tipo="text" valor={form.titulo} onChange={e => setForm({...form, titulo: e.target.value})} placeholder={MEITI.t('what_to_do', null, '¿Qué hay que hacer?')} />
          <UI.Campo etiqueta={MEITI.t('description', null, 'Descripción')} tipo="textarea" valor={form.descripcion} onChange={e => setForm({...form, descripcion: e.target.value})} placeholder={MEITI.t('additional_details', null, 'Detalles adicionales...')} />

          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <UI.Campo etiqueta={MEITI.t('date', null, 'Fecha')} tipo="date" valor={form.fecha} onChange={e => setForm({...form, fecha: e.target.value})} />
            </div>
            <div className="flex-1">
              <UI.Campo etiqueta={MEITI.t('priority', null, 'Prioridad')} tipo="select" valor={form.prioridad_id} onChange={e => setForm({...form, prioridad_id: e.target.value})} opciones={[{value:'', label: MEITI.t('no_priority', null, 'Sin prioridad')}, ...prioridades.map(p => ({value: p.id, label: p.nombre}))]} />
            </div>
          </div>

          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <UI.Campo etiqueta={MEITI.t('project', null, 'Proyecto')} tipo="select" valor={form.proyecto_id} onChange={e => setForm({...form, proyecto_id: e.target.value})} opciones={[{value:'', label: MEITI.t('inbox', null, 'Bandeja de entrada')}, ...proyectos.map(p => ({value: p.id, label: p.nombre}))]} />
            </div>
            <div className="flex-1">
              <UI.Campo etiqueta={MEITI.t('repetition', null, 'Repetición')} tipo="select" valor={form.regla_repeticion} onChange={e => setForm({...form, regla_repeticion: e.target.value})} opciones={[{value:'none', label: MEITI.t('no_repeat', null, 'No repetir')}, {value:'diaria', label: MEITI.t('daily', null, 'Diaria')}, {value:'semanal', label: MEITI.t('weekly', null, 'Semanal')}, {value:'mensual', label: MEITI.t('monthly', null, 'Mensual')}]} />
            </div>
          </div>

          <div className="mt-2">
            <UI.Boton onClick={guardar} disabled={guardando} className="w-full justify-center">
              <i className="fa-solid fa-save mr-2"></i> {guardando ? MEITI.t('saving', null, 'Guardando...') : MEITI.t('save_task', null, 'Guardar Tarea')}
            </UI.Boton>
          </div>
        </div>
      </UI.Tarjeta>

      {tareaId && (
        <UI.Tarjeta className="p-5">
          <h3 className="font-bold mb-4 text-lg" style={{ color: tema.texto }}>
            <i className="fa-solid fa-list-check mr-2" style={{ color: tema.colorSecundario }}></i>
            {MEITI.t('subtasks', null, 'Subtareas')}
          </h3>

          <div className="mb-6">
            <UI.TablaDatos
              columnas={[
                { clave: 'titulo', etiqueta: MEITI.t('title', null, 'Título') },
                {
                  clave: 'completada',
                  etiqueta: MEITI.t('status', null, 'Estado'),
                  render: (f) => <UI.Chip tono={f.completada ? 'exito' : 'neutro'}>{f.completada ? MEITI.t('completed', null, 'Completada') : MEITI.t('pending', null, 'Pendiente')}</UI.Chip>
                }
              ]}
              datos={subtareas}
              claveId="id"
              onEditar={(fila) => setSubtareaEditando(fila)}
              onBorrar={(fila) => borrarSubtarea(fila.id)}
              accionesExtra={[
                {
                  etiqueta: (f) => f.completada ? MEITI.t('mark_pending', null, 'Marcar pendiente') : MEITI.t('mark_completed', null, 'Completar'),
                  icono: 'fa-check',
                  tono: (f) => f.completada ? 'neutro' : 'exito',
                  onClick: toggleSubtarea
                }
              ]}
            />
          </div>

          {subtareaEditando ? (
            <div style={{ display: 'flex', gap: '0.75rem', alignItems: 'flex-end' }}>
              <div className="flex-1">
                <UI.Campo
                  etiqueta={MEITI.t('edit_subtask', null, 'Editar subtarea')}
                  tipo="text"
                  valor={subtareaEditando.titulo}
                  onChange={e => setSubtareaEditando({...subtareaEditando, titulo: e.target.value})}
                />
              </div>
              <UI.Boton onClick={guardarEdicionSubtarea}>{MEITI.t('save', null, 'Guardar')}</UI.Boton>
              <UI.Boton variante="secundario" onClick={() => setSubtareaEditando(null)}>{MEITI.t('cancel', null, 'Cancelar')}</UI.Boton>
            </div>
          ) : (
            <UI.Campo
              etiqueta={MEITI.t('new_subtask', null, 'Nueva subtarea')}
              tipo="text"
              valor={nuevaSub}
              onChange={e => setNuevaSub(e.target.value)}
              placeholder={MEITI.t('new_subtask_placeholder', null, 'Escribe y presiona Agregar...')}
              accion={<UI.Boton onClick={agregarSubtarea}>{MEITI.t('add', null, 'Agregar')}</UI.Boton>}
            />
          )}
        </UI.Tarjeta>
      )}
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const [tareas, setTareas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const cargar = async () => {
      setCargando(true);
      const res = await MEITI.fetchDatosPropios(`/api/boveda/${MEITI.obtenerTabla('mt_tareas')}?ecosistema=${eco}`);
      if (res.ok) {
        setTareas(res.registros || []);
      } else {
        setError(res.error || MEITI.t('err_load_tasks', null, 'Error al cargar las tareas.'));
      }
      setCargando(false);
    };
    cargar();
  }, []);

  if (cargando) {
    return (
      <UI.Tarjeta>
        <div className="p-12 flex justify-center items-center">
          <Iconos.LoaderCircle size={40} className="animate-spin" color={tema.colorPrimario} />
        </div>
      </UI.Tarjeta>
    );
  }

  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);

  const ultimos7Dias = Array.from({ length: 7 }).map((_, i) => {
    const d = new Date(hoy);
    d.setDate(d.getDate() - (6 - i));
    return d.toISOString().split('T')[0];
  });

  const completadas = tareas.filter(t => String(t.completada) === '1' && t.fecha_completada);
  const porDia = {};
  completadas.forEach(t => {
    const fecha = t.fecha_completada.split('T')[0];
    porDia[fecha] = (porDia[fecha] || 0) + 1;
  });

  const datosGrafico = ultimos7Dias.map(fecha => {
    const [y, m, d] = fecha.split('-');
    return {
      fechaOriginal: fecha,
      dia: `${d}/${m}`,
      completadas: porDia[fecha] || 0
    };
  });

  const totalSemana = datosGrafico.reduce((acc, curr) => acc + curr.completadas, 0);
  const maxDia = Math.max(...datosGrafico.map(d => d.completadas));

  let racha = 0;
  let fechaCheck = new Date(hoy);
  const hoyStr = fechaCheck.toISOString().split('T')[0];

  if (porDia[hoyStr] > 0) {
    racha++;
    fechaCheck.setDate(fechaCheck.getDate() - 1);
  } else {
    fechaCheck.setDate(fechaCheck.getDate() - 1);
  }

  while (true) {
    const checkStr = fechaCheck.toISOString().split('T')[0];
    if (porDia[checkStr] > 0) {
      racha++;
      fechaCheck.setDate(fechaCheck.getDate() - 1);
    } else {
      break;
    }
  }

  return (
    <div className="flex flex-col gap-6">
      <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Animacion.motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-4">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: tema.colorPrimario + '22', color: tema.colorPrimario }}>
              <Iconos.Flame size={28} />
            </div>
            <div>
              <p className="text-xs font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('current_streak', null, 'Racha Actual')}</p>
              <h3 className="text-3xl font-black" style={{ color: tema.texto }}>{racha} <span className="text-lg opacity-70 font-bold">{MEITI.t('days', null, 'días')}</span></h3>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.1 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-4">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: tema.colorSecundario + '22', color: tema.colorSecundario }}>
              <Iconos.CheckCheck size={28} />
            </div>
            <div>
              <p className="text-xs font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('completed_7d', null, 'Últimos 7 días')}</p>
              <h3 className="text-3xl font-black" style={{ color: tema.texto }}>{totalSemana} <span className="text-lg opacity-70 font-bold">{MEITI.t('tasks_short', null, 'tareas')}</span></h3>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>

        <Animacion.motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.2 }}>
          <UI.Tarjeta className="flex items-center gap-4 p-4">
            <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: tema.texto + '11', color: tema.texto }}>
              <Iconos.Trophy size={28} />
            </div>
            <div>
              <p className="text-xs font-bold opacity-70 uppercase tracking-wider" style={{ color: tema.texto }}>{MEITI.t('best_day', null, 'Mejor Día')}</p>
              <h3 className="text-3xl font-black" style={{ color: tema.texto }}>{maxDia} <span className="text-lg opacity-70 font-bold">{MEITI.t('tasks_short', null, 'tareas')}</span></h3>
            </div>
          </UI.Tarjeta>
        </Animacion.motion.div>
      </div>

      <Animacion.motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.3, delay: 0.3 }}>
        <UI.Tarjeta className="flex flex-col gap-6 p-6">
          <div className="flex items-center gap-3">
            <Iconos.TrendingUp size={24} color={tema.colorPrimario} />
            <h2 className="text-xl font-bold" style={{ color: tema.texto }}>{MEITI.t('performance_chart', null, 'Rendimiento Semanal')}</h2>
          </div>

          {totalSemana === 0 ? (
            <UI.EstadoVacio icono="fa-chart-simple" mensaje={MEITI.t('no_data_chart', null, 'Completa tareas para ver tu progreso en el gráfico.')} />
          ) : (
            <div className="w-full h-80">
              <Graficos.ResponsiveContainer width="100%" height="100%">
                <Graficos.BarChart data={datosGrafico} margin={{ top: 20, right: 10, left: -20, bottom: 0 }}>
                  <Graficos.CartesianGrid strokeDasharray="3 3" stroke={tema.texto + '22'} vertical={false} />
                  <Graficos.XAxis dataKey="dia" stroke={tema.texto} opacity={0.7} tick={{ fontSize: 12, fontWeight: 600 }} axisLine={false} tickLine={false} dy={10} />
                  <Graficos.YAxis stroke={tema.texto} opacity={0.7} tick={{ fontSize: 12, fontWeight: 600 }} axisLine={false} tickLine={false} allowDecimals={false} dx={-10} />
                  <Graficos.Tooltip 
                    cursor={{ fill: tema.texto + '0D' }}
                    contentStyle={{ backgroundColor: tema.superficie, borderColor: tema.colorPrimario + '33', borderRadius: '1rem', color: tema.texto, boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.1)' }}
                    itemStyle={{ color: tema.colorPrimario, fontWeight: '900' }}
                  />
                  <Graficos.Bar dataKey="completadas" name={MEITI.t('tasks', null, 'Tareas completadas')} fill={tema.colorPrimario} radius={[6, 6, 0, 0]} maxBarSize={60} />
                </Graficos.BarChart>
              </Graficos.ResponsiveContainer>
            </div>
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const tabla = MEITI.obtenerTabla('mt_etiquetas');
  const urlBase = `/api/boveda/${tabla}?ecosistema=${eco}`;

  const [etiquetas, setEtiquetas] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const vacio = { id: '', nombre: '', color: '#3b82f6' };
  const [form, setForm] = useState(vacio);

  const paleta = ['#ef4444', '#f97316', '#f59e0b', '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#6366f1', '#8b5cf6', '#a855f7', '#d946ef', '#ec4899', '#64748b'];

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatosPropios(urlBase);
    if (res.ok) setEtiquetas(res.registros || []);
    else setError(res.error || MEITI.t('err_load_tags', null, 'Error al cargar etiquetas.'));
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setError(null); setExito(null);
    if (!form.nombre.trim()) return setError(MEITI.t('err_name_req', null, 'El nombre es obligatorio.'));

    setGuardando(true);
    const esNuevo = !form.id;
    const payload = {
      id: esNuevo ? 'tag_' + Date.now() : form.id,
      usuario_id: uid,
      nombre: form.nombre.trim(),
      color: form.color
    };

    await MEITI.mutar(urlBase, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('tag_saved', null, 'Etiqueta guardada.'));
        setForm(vacio);
        cargar();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_save_tag', null, 'Error al guardar.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('del_tag_q', null, '¿Borrar esta etiqueta?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null); setExito(null);
    await MEITI.mutar(`${urlBase}&id=${id}`, { method: 'DELETE' }, {
      alLograr: () => {
        setExito(MEITI.t('tag_deleted', null, 'Etiqueta eliminada.'));
        if (form.id === id) setForm(vacio);
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('err_del_tag', null, 'Error al eliminar.'))
    });
  };

  const editar = (fila) => {
    setForm({ id: fila.id, nombre: fila.nombre, color: fila.color || '#3b82f6' });
  };

  const columnas = [
    { clave: 'color', etiqueta: MEITI.t('col_color', null, 'Color'), render: (f) => <div className="w-6 h-6 rounded-full shadow-sm" style={{ backgroundColor: f.color }}></div> },
    { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') }
  ];

  return (
    <div className="flex flex-col gap-6">
      <Animacion.motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25 }}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.Tags size={20} color={tema.colorPrimario} />
            <UI.Etiqueta>{form.id ? MEITI.t('edit_tag', null, 'Editar Etiqueta') : MEITI.t('new_tag', null, 'Nueva Etiqueta')}</UI.Etiqueta>
          </div>
          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

          <form onSubmit={guardar} className="flex flex-col gap-4">
            <div className="flex flex-col md:flex-row gap-4">
              <div className="flex-1">
                <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre')} tipo="text" valor={form.nombre} onChange={e => setForm({...form, nombre: e.target.value})} placeholder={MEITI.t('ph_tag_name', null, 'Ej: Urgente, Casa, Trabajo')} />
              </div>
            </div>
            <div className="flex flex-col gap-2">
              <UI.Etiqueta>{MEITI.t('f_color', null, 'Color')}</UI.Etiqueta>
              <div className="flex flex-wrap gap-3">
                {paleta.map(c => (
                  <button
                    key={c}
                    type="button"
                    onClick={() => setForm({...form, color: c})}
                    className={`w-8 h-8 rounded-full transition-transform ${form.color === c ? 'scale-125 ring-2 ring-offset-2' : 'hover:scale-110'}`}
                    style={{ backgroundColor: c, ringColor: c, ringOffsetColor: tema.superficie }}
                    aria-label={`Seleccionar color ${c}`}
                  />
                ))}
              </div>
            </div>
            <div className="flex gap-2 mt-2">
              <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                <span className="flex items-center gap-2"><Iconos.Save size={16} /> {guardando ? MEITI.t('saving', null, 'Guardando...') : (form.id ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_create', null, 'Crear'))}</span>
              </UI.Boton>
              {form.id && (
                <UI.Boton tipo="button" variante="secundario" onClick={() => setForm(vacio)}>
                  <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                </UI.Boton>
              )}
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <Animacion.motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25, delay: 0.1 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Iconos.List size={20} color={tema.colorSecundario} />
            <UI.Etiqueta>{MEITI.t('tag_list', null, 'Etiquetas Guardadas')}</UI.Etiqueta>
          </div>
          {cargando ? (
            <p style={{color: tema.texto}}>{MEITI.t('loading', null, 'Cargando...')}</p>
          ) : etiquetas.length === 0 ? (
            <UI.EstadoVacio icono="fa-tags" mensaje={MEITI.t('empty_tags', null, 'No hay etiquetas creadas.')} />
          ) : (
            <UI.TablaDatos columnas={columnas} datos={etiquetas} claveId="id" onEditar={editar} onBorrar={(fila) => borrar(fila.id)} />
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const uid = MEITI.obtenerUsuarioActual();
  const tabla = MEITI.obtenerTabla('mt_prioridades');
  const urlBase = `/api/boveda/${tabla}?ecosistema=${eco}`;

  const [prioridades, setPrioridades] = useState([]);
  const [cargando, setCargando] = useState(true);
  const [guardando, setGuardando] = useState(false);
  const [error, setError] = useState(null);
  const [exito, setExito] = useState(null);

  const vacio = { id: '', nivel: '', nombre: '', color: '#ef4444' };
  const [form, setForm] = useState(vacio);

  const paleta = ['#ef4444', '#f97316', '#f59e0b', '#84cc16', '#10b981', '#06b6d4', '#3b82f6', '#6366f1', '#8b5cf6', '#a855f7', '#d946ef', '#ec4899', '#64748b'];

  const cargar = async () => {
    setCargando(true);
    const res = await MEITI.fetchDatosPropios(urlBase);
    if (res.ok) {
      const ordenadas = (res.registros || []).sort((a, b) => Number(a.nivel) - Number(b.nivel));
      setPrioridades(ordenadas);
    } else {
      setError(res.error || MEITI.t('err_load_prio', null, 'Error al cargar prioridades.'));
    }
    setCargando(false);
  };

  useEffect(() => { cargar(); }, []);

  const guardar = async (e) => {
    e.preventDefault();
    setError(null); setExito(null);
    if (!form.nombre.trim() || !form.nivel) return setError(MEITI.t('err_prio_req', null, 'El nombre y el nivel son obligatorios.'));

    setGuardando(true);
    const esNuevo = !form.id;
    const payload = {
      id: esNuevo ? 'prio_' + Date.now() : form.id,
      usuario_id: uid,
      nivel: Number(form.nivel),
      nombre: form.nombre.trim(),
      color: form.color
    };

    await MEITI.mutar(urlBase, {
      method: esNuevo ? 'POST' : 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    }, {
      alLograr: () => {
        setExito(MEITI.t('prio_saved', null, 'Prioridad guardada.'));
        setForm(vacio);
        cargar();
        setGuardando(false);
      },
      alFallar: (err) => {
        setError(err || MEITI.t('err_save_prio', null, 'Error al guardar.'));
        setGuardando(false);
      }
    });
  };

  const borrar = async (id) => {
    if (!await MEITI.confirmar(MEITI.t('del_prio_q', null, '¿Borrar esta prioridad?'), { titulo: MEITI.t('delete', null, 'Borrar'), confirmar: MEITI.t('yes_delete', null, 'Sí, borrar'), tono: 'peligro' })) return;
    setError(null); setExito(null);
    await MEITI.mutar(`${urlBase}&id=${id}`, { method: 'DELETE' }, {
      alLograr: () => {
        setExito(MEITI.t('prio_deleted', null, 'Prioridad eliminada.'));
        if (form.id === id) setForm(vacio);
        cargar();
      },
      alFallar: (err) => setError(err || MEITI.t('err_del_prio', null, 'Error al eliminar.'))
    });
  };

  const editar = (fila) => {
    setForm({ id: fila.id, nivel: String(fila.nivel), nombre: fila.nombre, color: fila.color || '#ef4444' });
  };

  const columnas = [
    { clave: 'nivel', etiqueta: MEITI.t('col_level', null, 'Nivel'), tipo: 'numero' },
    { clave: 'color', etiqueta: MEITI.t('col_color', null, 'Color'), render: (f) => <div className="w-6 h-6 rounded-full shadow-sm" style={{ backgroundColor: f.color }}></div> },
    { clave: 'nombre', etiqueta: MEITI.t('col_name', null, 'Nombre') }
  ];

  return (
    <div className="flex flex-col gap-6">
      <Animacion.motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25 }}>
        <UI.Tarjeta>
          <div className="flex items-center gap-2 mb-4">
            <Iconos.Flag size={20} color={tema.colorPrimario} />
            <UI.Etiqueta>{form.id ? MEITI.t('edit_prio', null, 'Editar Prioridad') : MEITI.t('new_prio', null, 'Nueva Prioridad')}</UI.Etiqueta>
          </div>
          <UI.Aviso mensaje={error} tono="peligro" onCerrar={() => setError(null)} />
          <UI.Aviso mensaje={exito} tono="exito" onCerrar={() => setExito(null)} />

          <form onSubmit={guardar} className="flex flex-col gap-4">
            <div className="flex flex-col md:flex-row gap-4">
              <div className="flex-1">
                <UI.Campo etiqueta={MEITI.t('f_level', null, 'Nivel (1 es más alto)')} tipo="number" valor={form.nivel} onChange={e => setForm({...form, nivel: e.target.value})} placeholder="1" />
              </div>
              <div className="flex-1">
                <UI.Campo etiqueta={MEITI.t('f_name', null, 'Nombre')} tipo="text" valor={form.nombre} onChange={e => setForm({...form, nombre: e.target.value})} placeholder={MEITI.t('ph_prio_name', null, 'Ej: Alta, Media, Baja')} />
              </div>
            </div>
            <div className="flex flex-col gap-2">
              <UI.Etiqueta>{MEITI.t('f_color', null, 'Color')}</UI.Etiqueta>
              <div className="flex flex-wrap gap-3">
                {paleta.map(c => (
                  <button
                    key={c}
                    type="button"
                    onClick={() => setForm({...form, color: c})}
                    className={`w-8 h-8 rounded-full transition-transform ${form.color === c ? 'scale-125 ring-2 ring-offset-2' : 'hover:scale-110'}`}
                    style={{ backgroundColor: c, ringColor: c, ringOffsetColor: tema.superficie }}
                    aria-label={`Seleccionar color ${c}`}
                  />
                ))}
              </div>
            </div>
            <div className="flex gap-2 mt-2">
              <UI.Boton tipo="submit" variante="primario" disabled={guardando}>
                <span className="flex items-center gap-2"><Iconos.Save size={16} /> {guardando ? MEITI.t('saving', null, 'Guardando...') : (form.id ? MEITI.t('btn_update', null, 'Actualizar') : MEITI.t('btn_create', null, 'Crear'))}</span>
              </UI.Boton>
              {form.id && (
                <UI.Boton tipo="button" variante="secundario" onClick={() => setForm(vacio)}>
                  <span className="flex items-center gap-2"><Iconos.X size={16} /> {MEITI.t('btn_cancel', null, 'Cancelar')}</span>
                </UI.Boton>
              )}
            </div>
          </form>
        </UI.Tarjeta>
      </Animacion.motion.div>

      <Animacion.motion.div initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.25, delay: 0.1 }}>
        <UI.Tarjeta className="flex flex-col gap-4">
          <div className="flex items-center gap-2">
            <Iconos.List size={20} color={tema.colorSecundario} />
            <UI.Etiqueta>{MEITI.t('prio_list', null, 'Prioridades Guardadas')}</UI.Etiqueta>
          </div>
          {cargando ? (
            <p style={{color: tema.texto}}>{MEITI.t('loading', null, 'Cargando...')}</p>
          ) : prioridades.length === 0 ? (
            <UI.EstadoVacio icono="fa-flag" mensaje={MEITI.t('empty_prio', null, 'No hay prioridades creadas.')} />
          ) : (
            <UI.TablaDatos columnas={columnas} datos={prioridades} claveId="id" onEditar={editar} onBorrar={(fila) => borrar(fila.id)} />
          )}
        </UI.Tarjeta>
      </Animacion.motion.div>
    </div>
  );
}

({ datos, tema, UI, MEITI }) => {
  const eco = MEITI.obtenerEcosistemaActual();
  const base = '/api/boveda/' + MEITI.obtenerTabla('configuracion_app');

  // 👑 El dueño SIEMPRE cuenta como admin, no solo quien esté en la tabla de roles. Es la regla que
  // ya costó caro una vez: un panel que mira nada más la tabla deja al dueño afuera de su propia
  // app apenas cambia de email.
  const soyAdmin = MEITI.soyDuenoDeLaApp() || MEITI.miRolEnLaApp() === 'admin';

  const [pestana, setPestana] = React.useState('ayuda');
  const [filas, setFilas] = React.useState([]);
  const [cargando, setCargando] = React.useState(true);
  const [aviso, setAviso] = React.useState(null);

  // Un solo formulario para las dos pestañas: lo que cambia es la sección donde escribe.
  const VACIO = { titulo: '', cuerpo: '', tono: 'neutro' };
  const [editando, setEditando] = React.useState(null);
  const [forma, setForma] = React.useState(VACIO);
  const [abierto, setAbierto] = React.useState(false);

  const cargar = async () => {
    setCargando(true);
    const r = await MEITI.fetchDatos(base + '?ecosistema=' + eco);
    if (r.ok) setFilas(r.registros);
    setCargando(false);
  };

  React.useEffect(() => { cargar(); }, []);

  const cerrarFormulario = () => { setAbierto(false); setEditando(null); setForma(VACIO); };

  const guardar = async () => {
    if (!forma.titulo.trim()) { setAviso('Ponle un título antes de guardar.'); return; }
    const fila = editando || {};
    // 🩹 /api/boveda hace INSERT OR REPLACE por "id": si no se mandan TODAS las columnas, las que
    // falten quedan en NULL al reemplazar. Por eso el cuerpo va completo siempre, no solo lo tocado.
    const cuerpo = {
      id: fila.id || (pestana + '_' + Date.now()),
      seccion: pestana,
      titulo: forma.titulo.trim(),
      cuerpo: forma.cuerpo,
      tono: forma.tono || 'neutro',
      orden: fila.orden != null ? fila.orden : filas.filter(f => f.seccion === pestana).length,
      fecha: fila.fecha || new Date().toISOString()
    };
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + (editando ? '&id=' + fila.id : ''), {
      method: editando ? 'PUT' : 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(cuerpo)
    });
    if (r && r.ok === false) { setAviso('No se pudo guardar. Vuelve a intentarlo.'); return; }
    setAviso(null);
    cerrarFormulario();
    cargar();
  };

  const borrar = async (fila) => {
    if (!await MEITI.confirmar('¿Borrar "' + (fila.titulo || 'este registro') + '"?', { titulo: MEITI.t('delete_action', null, 'Borrar'), confirmar: MEITI.t('delete_confirm', null, 'Sí, borrar'), tono: 'peligro' })) return;
    const r = await MEITI.fetchMutante(base + '?ecosistema=' + eco + '&id=' + fila.id, { method: 'DELETE' });
    if (r && r.ok === false) { setAviso('No se pudo borrar. Vuelve a intentarlo.'); return; }
    cargar();
  };

  const abrirEdicion = (fila) => {
    setEditando(fila);
    setForma({ titulo: fila.titulo || '', cuerpo: fila.cuerpo || '', tono: fila.tono || 'neutro' });
    setAbierto(true);
  };

  const deLaSeccion = filas.filter(f => (f.seccion || 'ayuda') === pestana);
  // La ayuda se lee en el orden en que el dueño la escribió; la bitácora, al revés: lo último
  // que pasó es lo primero que uno quiere ver.
  const visibles = pestana === 'ayuda'
    ? deLaSeccion.slice().sort((a, b) => (a.orden || 0) - (b.orden || 0))
    : deLaSeccion.slice().sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));

  const fechaLegible = (v) => {
    const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v || ''));
    if (!m) return '';
    const MESES = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
    return Number(m[3]) + ' ' + MESES[Number(m[2]) - 1] + ' ' + m[1];
  };

  const TONOS = [
    { value: 'neutro', label: MEITI.t('note_input', null, 'Nota') },
    { value: 'exito', label: MEITI.t('update_input', null, 'Actualización') },
    { value: 'alerta', label: MEITI.t('notice_input', null, 'Aviso') },
    { value: 'peligro', label: MEITI.t('error_input', null, 'Error') }
  ];
  const nombreDelTono = (t) => (TONOS.find(x => x.value === (t || 'neutro')) || TONOS[0]).label;

  const filaAyuda = (f) => (
    <div key={f.id} style={{ border: '1px solid ' + tema.colorPrimario + '22', borderRadius: '0.75rem', padding: '1rem', marginBottom: '0.75rem' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem' }}>
        <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        {soyAdmin && (
          <div style={{ display: 'flex', gap: '0.25rem', flexShrink: 0 }}>
            <UI.Boton variante="fantasma" ariaLabel={MEITI.t('edit_action', null, "Editar")} onClick={() => abrirEdicion(f)}><i className="fa-solid fa-pen-to-square"></i></UI.Boton>
            <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>
          </div>
        )}
      </div>
      {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.8, marginTop: '0.5rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
    </div>
  );

  const filaBitacora = (f) => (
    <div key={f.id} style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', gap: '0.75rem', borderBottom: '1px solid ' + tema.colorPrimario + '18', padding: '0.6rem 0' }}>
      <div style={{ minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexWrap: 'wrap' }}>
          <UI.Chip tono={f.tono || 'neutro'}>{nombreDelTono(f.tono)}</UI.Chip>
          <strong style={{ color: tema.texto }}>{f.titulo}</strong>
        </div>
        {f.cuerpo && <p style={{ color: tema.texto, opacity: 0.75, marginTop: '0.35rem', whiteSpace: 'pre-wrap' }}>{f.cuerpo}</p>}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', flexShrink: 0 }}>
        <span style={{ color: tema.texto, opacity: 0.5, fontSize: '0.75rem', whiteSpace: 'nowrap' }}>{fechaLegible(f.fecha)}</span>
        {soyAdmin && <UI.Boton variante="fantasma-peligro" ariaLabel={MEITI.t('delete_action', null, "Borrar")} onClick={() => borrar(f)}><i className="fa-solid fa-trash-can"></i></UI.Boton>}
      </div>
    </div>
  );

  return (
    <UI.Tarjeta>
      <h3 style={{ color: tema.texto, fontSize: '1.2rem', fontWeight: 'bold', marginBottom: '0.25rem' }}>{MEITI.t('configuration_title', null, "Configuración")}</h3>
      <p style={{ color: tema.texto, opacity: 0.6, fontSize: '0.75rem', marginBottom: '1rem' }}>{MEITI.t('app_guide_description', null, "Cómo se usa esta app, y qué le fue pasando.")}</p>

      {aviso && <UI.Aviso mensaje={aviso} tono="alerta" onCerrar={() => setAviso(null)} />}

      <UI.Pestanas
        pestanas={[{ id: 'ayuda', titulo: MEITI.t('help_title', null, 'Ayuda'), icono: 'fa-circle-question' }, { id: 'bitacora', titulo: MEITI.t('changelog_title', null, 'Bitácora'), icono: 'fa-clock-rotate-left' }]}
        activa={pestana}
        onCambio={(id) => { setPestana(id); cerrarFormulario(); }}
        className="mb-4"
      />

      {cargando ? (
        <p style={{ color: tema.texto, opacity: 0.6 }}>{MEITI.t('loading', null, "Cargando...")}</p>
      ) : visibles.length === 0 ? (
        <UI.EstadoVacio
          icono={pestana === 'ayuda' ? 'fa-book-open' : 'fa-clock-rotate-left'}
          mensaje={pestana === 'ayuda'
            ? (soyAdmin ? 'Todavía no hay guía de uso. Escribe la primera sección y quien entre después va a saber cómo usar la app.' : 'Todavía no hay una guía para esta app.')
            : 'Todavía no hay nada anotado. Acá van a aparecer las actualizaciones, los avisos y los errores de esta app.'}
        />
      ) : pestana === 'ayuda' ? (
        <div>{visibles.map(filaAyuda)}</div>
      ) : (
        <UI.ListaScrollable alto="26rem">{visibles.map(filaBitacora)}</UI.ListaScrollable>
      )}

      {soyAdmin && (
        <div style={{ marginTop: '1.25rem', paddingTop: '1rem', borderTop: '1px solid ' + tema.colorPrimario + '22' }}>
          {!abierto ? (
            <UI.Boton variante="secundario" onClick={() => setAbierto(true)}>
              <i className="fa-solid fa-plus"></i> {pestana === 'ayuda' ? 'Agregar una sección a la guía' : 'Anotar en la bitácora'}
            </UI.Boton>
          ) : (
            <div>
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Título de la sección' : 'Qué pasó'}
                valor={forma.titulo}
                onChange={(e) => setForma({ ...forma, titulo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Cómo dar de alta un cliente' : 'Se actualizó el catálogo de precios'}
              />
              <div style={{ height: '0.75rem' }} />
              <UI.Campo
                etiqueta={pestana === 'ayuda' ? 'Explicación' : 'Detalle (opcional)'}
                tipo="textarea"
                filas={4}
                valor={forma.cuerpo}
                onChange={(e) => setForma({ ...forma, cuerpo: e.target.value })}
                placeholder={pestana === 'ayuda' ? 'Explícalo como se lo explicarías a alguien que abre la app por primera vez' : 'Qué se cambió y por qué'}
              />
              {pestana === 'bitacora' && (
                <div style={{ marginTop: '0.75rem' }}>
                  <UI.Campo etiqueta={MEITI.t('type_input', null, "Tipo")} tipo="select" valor={forma.tono} onChange={(e) => setForma({ ...forma, tono: e.target.value })} opciones={TONOS} />
                </div>
              )}
              <div style={{ height: '0.75rem' }} />
              <div style={{ display: 'flex', gap: '0.5rem' }}>
                <UI.Boton onClick={guardar}>{editando ? 'Guardar cambios' : 'Guardar'}</UI.Boton>
                <UI.Boton variante="secundario" onClick={cerrarFormulario}>{MEITI.t('cancel_button', null, "Cancelar")}</UI.Boton>
              </div>
            </div>
          )}
        </div>
      )}
    </UI.Tarjeta>
  );
}
